  budgetVsActualSnapshot(ctx,entityId,start,end,pnl){const budget=this.collection(ctx,'budgets').filter(row=>(!entityId||row.legal_entity_id===entityId)&&row.status==='APPROVED'&&(!start||row.end_date>=start)&&(!end||row.start_date<=end)).sort((a,b)=>b.version-a.version||Date.parse(b.created_at)-Date.parse(a.created_at))[0];if(!budget)return {available:false,reason:'Geen goedgekeurd budget ingeladen'};const actualByAccount=new Map(pnl.map(row=>[row.account_id,row.balance_cents])),rows=budget.lines.map(line=>({account_id:line.account_id,budget_cents:line.amount_cents,actual_cents:actualByAccount.get(line.account_id)||0,variance_cents:(actualByAccount.get(line.account_id)||0)-line.amount_cents}));return {available:true,budget_id:budget.id,budget_version:budget.version,rows,budget_cents:sum(rows,'budget_cents'),actual_cents:sum(rows,'actual_cents'),variance_cents:sum(rows,'variance_cents')}}
