  export(context,principalInput,scopeInput,formatInput='CSV',options={}){const {ctx,principal}=this.scope(context,principalInput);requirePermission(principal,'finance:export');const scope=String(scopeInput||'').toLowerCase(),allowed=new Set(['journal_entries','journal_lines','invoices','payments','bank_transactions','reconciliations','audit_events']),format=String(formatInput||'CSV').toUpperCase();if(!allowed.has(scope))throw financeError(404,'finance_export_scope_invalid','Niet-ondersteunde financiële export');if(!['CSV','JSON'].includes(format))throw financeError(422,'finance_export_format_invalid','Finance-export ondersteunt CSV of JSON');const entityId=safeId(options.legal_entity_id),from=options.from?iso(options.from):null,to=options.to?iso(options.to):null;let rows=this.collection(ctx,scope).filter(row=>(!entityId||row.legal_entity_id===entityId)&&(!from||String(row.date||row.created_at||'')>=from)&&(!to||String(row.date||row.created_at||'')<=to));if(rows.length>50000)throw financeError(413,'finance_export_too_large','Verklein het exportbereik tot maximaal 50.000 records');rows=clone(rows);this.audit(ctx,principal,'EXPORT',scope,null,'Authorized tenant-scoped finance export',{format,count:rows.length,legal_entity_id:entityId,from,to});this.commit();const metadata={format,count:rows.length,tenant_id:ctx.tenant_id,dealer_id:ctx.dealer_id,legal_entity_id:entityId||null,range:{from,to},audited:true,permission_checked:'finance:export',privacy_classification:'FINANCIAL',no_secrets:true,exported_at:this.now()};if(format==='JSON')return {...metadata,records:rows};const keys=[...new Set(rows.flatMap(Object.keys))].filter(key=>!/(?:password|secret|token|authorization|cookie|private_key|api_key)/i.test(key)),escape=value=>`"${String(value??'').replace(/"/g,'""')}"`;return {...metadata,content:[keys.map(escape).join(','),...rows.map(row=>keys.map(key=>escape(typeof row[key]==='object'?JSON.stringify(row[key]):row[key])).join(','))].join('\n')};}
